def make_key(store, job_text, profile_version, criteria_version, compute):
    if store is None:
        return None
    key = f"{store}:{job_text}:{profile_version}:{criteria_version}"
    return key

from cache import make_key
def score(store, job_text, profile_version, criteria_version, compute):
    k = make_key(store, job_text, profile_version, criteria_version, compute)
    if k is None:
        return compute()
    if k not in store:
        store[k] = compute()
    return store[k]
